const WOUND_ECHO_SIGNATURE=['砕傷の伝播',26,8,'敵1体へ3秒の印。その間に減ったHPの40%を、対象の周囲160にいる別の敵へ放つ（スキル基礎威力600%が上限）。印の相手へ直接は当たらず、先に倒すと不発。回復したHPは減少量から差し引く。対象が500を超える・壁に隠れる・消える・自分の死亡や地域移動で解除。範囲補正は伝播の半径だけに作用。再発動は置き換え。','M26 7L35 20L26 33L17 20ZM26 33V47M9 32L3 39L12 44M43 32L49 39L40 44M17 29L9 39M35 29L43 39'];
SIGNATURE_SKILLS.push(WOUND_ECHO_SIGNATURE);Object.assign(GEM.crafted_5_7,{name:WOUND_ECHO_SIGNATURE[0],cost:26,cool:8,desc:WOUND_ECHO_SIGNATURE[3],ability:null,signature:103,tags:['spell','area']});
SIGNATURE_AUDIO.push(['woundecho',350,.35]);SKILL_AUDIO_FAMILIES.heavy.add('woundecho');
function woundEchoValid(s){const e=s.target;return s.owner===p&&s.world===dungeon&&!s.finished&&!dead&&p?.hp>0&&e?.hp>0&&Number.isFinite(e.hp)&&enemies.includes(e)&&dist(p,e)<=500&&lineClear(p,e);}
function woundEchoDamage(s){return Math.min(s.damage*6,Math.max(0,s.startHP-s.target.hp)*.4);}
const woundEchoCastBase=castCraftedSkill;castCraftedSkill=(build,...args)=>{const result=woundEchoCastBase(build,...args);if(GEM[build.type]?.signature!==103)return result;const s=signatureSpells.at(-1);if(s?.mode!==103)return result;signatureSpells=signatureSpells.filter(v=>v.mode!==103||v===s);Object.assign(s,{owner:p,world:dungeon,finished:false,startHP:s.target?.hp||0});if(!woundEchoValid(s)){s.finished=true;signatureSpells=signatureSpells.filter(v=>v!==s);say('照準付近の敵に印を付けられません');}return result;};
const woundEchoStepBase=stepSignature;stepSignature=(s,dt)=>{if(s.mode!==103)return woundEchoStepBase(s,dt);if(!woundEchoValid(s)){s.finished=true;return false;}if(paused||!Number.isFinite(dt)||dt<=0)return true;s.time+=dt;if(s.time+1e-8<3)return true;s.finished=true;const source=s.target,damage=woundEchoDamage(s),center={x:source.x,y:source.y};if(damage<=0)return false;const targets=enemies.filter(e=>e!==source&&e.hp>0&&dist(e,center)<=160*s.build.radius&&lineClear(center,e));for(const e of targets)if(e.hp>0&&enemies.includes(e))spellHit(e,damage,s.build);burst(center.x,center.y,160*s.build.radius,ELEMENTS[s.build.elements[0]].color);playSignatureAudio(103,true,center.x,center.y);return false;};
const woundEchoPaintBase=paintSignatureSpells;paintSignatureSpells=()=>{woundEchoPaintBase();const renderList=signatureRenderList(103,103);if(!renderList.length)return;for(const s of renderList){if(s.mode!==103||!woundEchoValid(s)||!visibleAt(s.target.x,s.target.y))continue;const e=s.target,color=ELEMENTS[s.build.elements[0]].color;groundRing(e.x,e.y,160*s.build.radius,color,1);groundRing(e.x,e.y,30*Math.max(0,1-s.time/3),'#f5d48c',3);paintLinkLine({x:e.x-15,y:e.y-15},{x:e.x+15,y:e.y+15},color,2);}};
const woundEchoStatusBase=controlSkillStatus;controlSkillStatus=s=>s.mode===103?{label:'伝播 '+Math.round(woundEchoDamage(s))+' · '+Math.max(0,3-s.time).toFixed(1)+'秒',value:Math.min(1,s.time/3),waiting:true}:woundEchoStatusBase(s);

